#!/usr/bin/env python3
"""Source-local leaf contract with measured selected receiver caps.
166.667ps min/max IO envelope is explicit; it is NOT measured die routing.
No clock cut, false path or zero root load. Actual quarter source uses clk_sm.
"""
import argparse,json,hashlib
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--loads',type=Path,required=True);p.add_argument('--out',type=Path,required=True);p.add_argument('--NO',type=int,required=True);a=p.parse_args()
assert a.NO in (2,3)
tables={c:json.loads((a.loads/f'caps_{c}.json').read_text()) for c in ('ss','ff')}
lines=['# SS60/FF25 actual mapped source-local receiver; actual die RC/insertion OPEN.','create_clock -name clk_sm -period 833.333333 [get_ports clk_sm]','set prev [get_ports clk_sm]','set master clk_sm','for {set i 0} {$i<4} {incr i} {',' set roots {}',' foreach p [get_pins -hierarchical *] {','  if {[regexp "u_clk${i}.*/Y$" [get_full_name $p]]} {lappend roots $p}',' }',' if {[llength $roots]!=1} {error "missing real kept station forwarding inverter $i"}',' create_generated_clock -name forwarded$i -source $prev -master_clock $master -divide_by 1 -invert [lindex $roots 0]',' set prev [lindex $roots 0];set master forwarded$i','}','create_generated_clock -name forwarded_port -source $prev -master_clock $master -divide_by 1 [get_ports fclk_o]','set_clock_uncertainty -setup 60 [all_clocks]','set_clock_uncertainty -hold 25 [all_clocks]','foreach p [all_inputs] {',' if {[get_full_name $p] eq "clk_sm"} {continue}',' set_input_delay -min 0 -clock clk_sm $p',' set_input_delay -max 166.666667 -clock clk_sm $p','}','foreach p [all_outputs] {',' if {[get_full_name $p] eq "fclk_o"} {continue}',' set_output_delay -min 0 -clock clk_sm $p',' set_output_delay -max 166.666667 -clock clk_sm $p','}','set_max_fanout 32 [current_design]']
for corner in ('ss','ff'):
 for name,cap in tables[corner].items():
  assert cap>0
  lines.append(f'set {{cap_{corner}({name})}} {cap:.12g}')
lines+=['foreach p [all_outputs] {',' set n [get_full_name $p]',' set receiver {}',' if {[regexp {^out_data\[([0-9]+)\]$} $n -> bit]} {set receiver [format {in_data[%d]} [expr {$bit%2063}]]}',' if {[regexp {^out_owner\[([0-9]+)\]$} $n -> bit]} {set receiver [format {in_owner[%d]} [expr {$bit%192}]]}',' if {[regexp {^out_frame\[([0-9]+)\]$} $n -> bit]} {set receiver [format {in_frame[%d]} [expr {$bit%73}]]}',' if {[regexp {^out_v\[[0-9]+\]$} $n]} {set receiver in_v}',f' if {{$n eq "in_r" || $n eq "release_r"}} {{set receiver {{out_r[{a.NO-1}]}}}}',' if {$n eq "release_v"} {set receiver {ACK_v[0]}}',' if {[regexp {^release_owner\[([0-9]+)\]$} $n -> bit]} {set receiver [format {ACK_owner[%d]} $bit]}',' if {[regexp {^release_frame\[([0-9]+)\]$} $n -> bit]} {set receiver [format {ACK_frame[%d]} $bit]}',' if {$n in {fault paused drained}} {set receiver in_v}',' if {$n eq "fclk_o"} {set receiver clk_sm}',' if {$receiver eq "" || ![info exists cap_ss($receiver)] || ![info exists cap_ff($receiver)]} {error "unbound actual mapped receiver $n -> $receiver"}',' set_load -max $cap_ss($receiver) $p',' set_load -min $cap_ff($receiver) $p','}']
a.out.write_text('\n'.join(lines)+'\n')
a.out.with_suffix('.json').write_text(json.dumps(dict(NO=a.NO,source_local=True,installed_die_context=False,clock_source='actual clk_sm/por_n selected publication-parent quarter; outgoing 4inverters retained, not a borrowed leaf clock',IO_envelope_max_ps=166.666667,IO_envelope_min_ps=0,IO_envelope_is_measured_parent=False,clock_root_load='measured actual adjacent selected station clock sink sum before CTS; conservative source-local load, not zero/free cut',data_outputs='same source-local selected native-station packet input, not a claim of installed SM receiver caps',status_outputs='source-local in_v load envelope; actual enclosing die controller remains OPEN',receiver_manifest_sha256=hashlib.sha256((a.loads/'receiver.json').read_bytes()).hexdigest(),sdc_sha256=hashlib.sha256(a.out.read_bytes()).hexdigest(),SS_setup_ps=60,FF_hold_ps=25,parent_closed=False),indent=2)+'\n')
print('Source-local component contract generated; parent wire/CTS context OPEN')
